import { resolveEntireIntentContextForCommit } from '../../lib/entire/context.js';
import type { EntireIntentContext } from '../../lib/entire/context.js';

interface CommitResolution {
  commitSha: string;
  checkpointId: string | null;
  commitDiffPatch: string;
